import sys
sys.dont_write_bytecode=True
import additional_pfp_adapters_audit as a
a.record({
'stage_082.py':'Read all127 lines. Recomputes UTF-8 artifact digest, checks a pinned toy RSA root, delegation certify/release scopes and textbook modular signature equations. Explicitly labels the root as toy with published test exponent and disclaims unforgeability/revocation/expiry/padding. No real credential or signing material was accessed or used. This apparatus cannot independently authenticate production authorization merely by verifying this scheme.',
'stage_083.py':'Read all101 lines. Checks prior-input references, exact sum/product results, id/value record digests and current input pins. Digests exclude operation and input identities, so equal-valued derivations with different operations share a digest; coordinated edits can update all producer pins. This is snapshot consistency rather than immutable authenticated lineage history.',
'stage_084.py':'Read all120 lines. Closed schemas and pinned local implementations recompute gcd, sort, rational sum and nonoverlapping text count before comparing result digests. Reimplementation is the tool semantics here, not evidence an external tool ran. Correct guessed outputs are indistinguishable from previously executed ones and can legitimately match the digest.',
'stage_085.py':'Read all87 lines. Replays permission subset handoffs and final task membership, checking delegator rootedness. Ordinary recipients use the latest scope, but principal is exempted from any incoming handoff update; a principal self-handoff to read retains write despite general prose about self-handoff narrowing. Root scope and agent identities are supplied, not authenticated.',
'stage_086.py':'Read all95 lines. Full parent DAG acyclicity, at least one evidence link for each root, link resolution and witness content hashes are checked. Arbitrary text is a valid witness without a semantic predicate; agent labels are only strings. This proves structural provenance consistency, not truth of the evidence or agent execution.',
'stage_087.py':'Read all88 lines. Independently reruns three fixed list predicates, requires base acceptance, changed mutants, actual negative verdicts and matching reported results. Establishes the listed mutation outcomes only. It neither audits arbitrary checker code nor proves detection of all dangerous mutations.',
'stage_088.py':'Read all108 lines. Replays a bounded counter machine with exact naturals, validated registers/jumps and exact captured exit/state/step count. HALTED is checked before value/time limits, so an over-limit state at a halt instruction still counts as HALTED under this implementation priority. Correct TIMEOUT or LIMIT reports also PASS; PASS is not completion of the program or proof.',
'stage_089.py':'Read all110 lines. Recomputes pointwise error sums, exact marginal/joint laws and pairwise independence when requested; checks either sum of sup bounds or standard deviation squared with full dependence. Pairwise independence suffices for variance additivity but not general joint independence; standard-deviation bounds do not bound bias or worst-case error. Source clearly distinguishes these rules.',
'stage_090.py':'Read all120 lines. Exact ASCII splitter spans, hashes and complete coverage are checked; each span needs exactly one nonempty link or exception. Quantifier vocabulary affects diagnostic only because all spans must be covered. Formal-object links are not resolved or checked against source meaning, so syntactic coverage does not constitute semantic formalization.',
'stage_091.py':'Read all166 lines. Exhaustively evaluates prenex unary/binary relational formulas on source structures of sizes1..k<=3 with<=12 relation bits. Typed map is not required injective or onto; inverse dictionary overwrites collisions and fallback lookup lets an unmapped target symbol alias a source name. Independent control mapR->S with target-onlyR PASSes by reading sourceR, without a legitimate interpretation of targetR. Even on well-bound bijections result is finite-fragment equivalence, not all-model equivalence.',
'stage_092.py':'Read all116 lines. Exact resolution replay uses actual recomputed resolvents and ends at empty clause; SAT partial models must be consistent and hit every clause. Sound relative to supplied CNF. Already-empty-clause UNSAT cannot use a zero-step certificate because nonempty proof steps are mandatory, a bounded incompleteness; no Lean term or independent binary kernel execution is evidenced.',
'stage_093.py':'Read all163 lines. Evaluates loop-free source expressions and a bounded stack target on each declared input; checks both arms of every source branch, actual results and exact outcome table. This is finite differential validation rather than compiler correctness. Syntactically unreachable branches make scope impossible; target loop computes up to fuel+1 nonhalt operations before FUEL, so beyond-budget malformed operations may affect error classification.',
'stage_094.py':'Read all86 lines. Nominal ports must be uniquely wired, opposite directions, type-equal and have some reverse flow between every connected component pair. This checks static wiring, not session ordering, data response pairing or runtime progress. Dotted names are concatenated without escaping and repeated component rows with disjoint port sets are merged.',
'stage_095.py':'Read all141 lines. Local pinned insertion/merge sorts are rerun, comparison counts/log hashes recomputed, and same-input ratios checked with positive candidate count. Environment is a fixed string plus local procedure definition, not actual host benchmarking. Log pairs refer to algorithm-local positions; no wall-clock performance, broad scaling or native speedup follows.',
'stage_096.py':'Read all103 lines. Recounts declared success/failure labels, binds corpus bytes to a supplied hash, and checks a clipped Chebyshev interval using the variance upper bound1/4. Binomial sampling and outcome truth are input assumptions. The prose says validity holds exactly when the bound inequality holds, but it is sufficient only: n1,h1 always yields[0,1], yet alpha1/10 is refused. Digest matching alone does not make a corpus historically immutable.',
'stage_097.py':'Read all101 lines. Applies four fixed list mutation operators, reruns selected fixed invariants and requires every changed mutant to fail its intended invariant with an exact sorted kill row. This is finite mutation evidence under declared danger/invariants, not arbitrary program mutation adequacy. Duplicate operation may make a65-entry mutant from an allowed64-entry base.',
'stage_098.py':'Read all174 lines. Reruns paired Euclidean/binary gcd, Newton/bisection integer roots, or two explicitly different rounding rules; exact agreeing cases merge and disagreeing cases remain listed. Distinct implementation names do not establish independent development/custody. Half-up rounds ties toward positive infinity, and half-even agrees on some ties, so prose saying they disagree exactly on ties overstates the disagreement set.',
'stage_099.py':'Read all110 lines. Replays a public toy LCG seed and checks each deletion/unit-decrement preserves a fixed failure predicate, ending at a local minimum under those moves. This is deterministic bounded reproduction, not unbiased generation or global minimum. No sealed seed/answer was read or solved; only this public source mechanism was inspected.',
'stage_100.py':'Read all97 lines. Checks finite claim/test/open references, explicit none authority and a frontier defined as claims without any test link. Test adequacy and outcomes are explicitly not decided. An OPEN claim also linked to a test is omitted from frontier and PASSes with an empty frontier, contradicting prose that an open obligation prevents completeness. Apparatus coverage is distinct from theorem certification.'
})
n=a.read('_notes.json')
specs=[
('ADAPT-F12',83,[11,101],'Derived record digests bind only id/value, not operation or input lineage; independent sum/product derivations share a digest. Historical immutability requires an external root/custody policy.','lineage_digest_omits_operation_sum'),
('ADAPT-F13',85,[14,87],'Principal self-handoff narrowing is ignored, unlike the general last-handoff prose. A read-only self-handoff followed by write task passes.','principal_self_handoff_does_not_narrow'),
('ADAPT-F14',91,[138,166],'Unmapped target relation can silently alias a source relation via rename fallback. A typed mapR->S does not bind target-onlyR, yet equivalence passes by evaluating sourceR.','unmapped_target_symbol_aliases_source_name'),
('ADAPT-F15',92,[82,111],'An initially empty-clause CNF cannot carry the natural zero-step refutation: checker refuses it as flag-without-proof. This is certificate incompleteness rather than unsound acceptance.','initial_empty_clause_has_no_zero_step_refutation'),
('ADAPT-F16',96,[16,103],'Chebyshev inequality is sufficient, not necessary for actual coverage; always-full[0,1] interval at n1,h1 is refused for alpha1/10 despite coverage1.','chebyshev_condition_not_necessary'),
('ADAPT-F17',100,[16,97],'An explicitly OPEN claim disappears from frontier once any declared test link exists, even though test adequacy/results are not checked.','open_tested_claim_absent_from_frontier')]
for id,num,lines,claim,control in specs:
    p=f'pfp/infrastructure/adapters/mssn_research/checkers/stage_{num:03}.py'
    n['findings'].append({'id':id,'claim':claim,'sources':[p],'source_ranges':[{'path':p,'sha256':a.sha(a.ROOT/p),'lines':lines}],'control':'_stage_probes2.json:'+control})
n['controls'].append({'path':'dag/reviews/additional_pfp_adapters_stage_probes2.json','status':'bounded_offline_controls','limits':'Seven small independently authored payloads; exact scope and interpretation limits retained.'})
a.write('_notes.json',n);a.report()
